@pytest.mark.parametrize("exc", (EOFError, KeyboardInterrupt))
def test_abort_exceptions_with_disabled_standalone_mode(runner, exc):
    @click.command()
    def cli():
        raise exc("catch me!")

    rv = runner.invoke(cli, standalone_mode=False)
    assert rv.exit_code == 1
    assert isinstance(rv.exception.__cause__, exc)
    assert rv.exception.__cause__.args == ("catch me!",)


def test_keyboard_interrupt_during_shell_completion(runner, monkeypatch):
    @click.command()
    def cli():
        pass

    def interrupt(*args):
        raise KeyboardInterrupt("catch me!")

    monkeypatch.setattr(cli, "_main_shell_completion", interrupt)
    rv = runner.invoke(cli, standalone_mode=False)

    assert isinstance(rv.exception, click.Abort)
    assert isinstance(rv.exception.__cause__, KeyboardInterrupt)
    assert rv.exception.__cause__.args == ("catch me!",)
    assert rv.output == "\n"


